def compute(vars):
    values = {
        "2018": vars["v1"],
        "2017": vars["v2"],
        "2016": vars["v3"],
    }
    largest_year = max(values, key=values.get)
    largest_value = values[largest_year]

    return {
        "value": largest_value,
        "trace": {
            "values": values,
            "largest_year": largest_year,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
